scwin.pageSize = "" + dma_pageContext.get("pageSize") + "";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_sessionFill();
        await scwin.init_loadList();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00200.onpageload' });
    }
};


